CREATE TABLE IF NOT EXISTS gis_layers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_code text UNIQUE NOT NULL, layer_name text NOT NULL, description text, authority_reference text, source_url text, data_license text, update_frequency text, layer_status text NOT NULL DEFAULT 'Planned', sensitivity text NOT NULL DEFAULT 'Public', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_spatial_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, external_feature_id text, feature_type text, properties jsonb NOT NULL DEFAULT '{}'::jsonb, geometry_json jsonb, geometry_status text NOT NULL DEFAULT 'Unverified', source_timestamp timestamptz, ingested_at timestamptz NOT NULL DEFAULT now(), UNIQUE(layer_id,external_feature_id));
CREATE TABLE IF NOT EXISTS gis_authoritative_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text UNIQUE NOT NULL, source_name text NOT NULL, source_url text NOT NULL, authority_level text NOT NULL DEFAULT 'PENDING', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_ward_authority_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text UNIQUE NOT NULL, authority_name text NOT NULL, evidence_scope text NOT NULL, source_url text NOT NULL, authority_level text NOT NULL DEFAULT 'CANDIDATE', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_ward_evidence_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), authority_key text NOT NULL, ward_code text, ward_name text, source_reference text NOT NULL, evidence_type text NOT NULL, content_hash text, source_version text, evidence_status text NOT NULL DEFAULT 'UNVERIFIED', reviewer_id text, reviewer_rationale text, created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_boundary_datasets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_name text NOT NULL, dataset_version text, geometry_format text NOT NULL, coordinate_reference_system text, boundary_level text NOT NULL, feature_count integer NOT NULL DEFAULT 0, geometry_status text NOT NULL DEFAULT 'Pending', validation_status text NOT NULL DEFAULT 'Pending', imported_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_boundary_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, area_code text NOT NULL, area_name text NOT NULL, boundary_level text NOT NULL, geometry_geojson jsonb, geometry_hash text, validation_status text NOT NULL DEFAULT 'Pending', source_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_geometry_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, dataset_name text NOT NULL, dataset_version text, source_url text, geometry_format text, geometry_crs text, feature_count integer, provenance jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'REGISTERED', imported_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,dataset_name,dataset_version));
CREATE TABLE IF NOT EXISTS gis_geometry_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES gis_geometry_sources(id), provider text NOT NULL, feature_id text NOT NULL, feature_name text, state_code text, parent_feature_id text, geometry_wkt text, geometry_geojson jsonb, normalized_geometry_available boolean NOT NULL DEFAULT false, geometry_valid boolean, geometry_empty boolean, source_srid text, normalized_srid text, validation_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,feature_id));
CREATE TABLE IF NOT EXISTS gis_current_exception_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version text NOT NULL, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, state_code text, category text NOT NULL, status text NOT NULL DEFAULT 'OPEN', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id));
CREATE TABLE IF NOT EXISTS gis_exception_candidate_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL, candidate_source text NOT NULL, state_name text NOT NULL, lga_name text NOT NULL, candidate_area_code text, confidence numeric NOT NULL, status text NOT NULL DEFAULT 'CANDIDATE_ONLY', evidence_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_ward_evidence_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, source_name text NOT NULL, source_url text, evidence_type text NOT NULL, authority_level text NOT NULL DEFAULT 'UNVERIFIED', artifact_sha256 text, excerpt text, state_name text, lga_name text, ward_name text, ward_code text, geometry_verified boolean NOT NULL DEFAULT false, provenance_verified boolean NOT NULL DEFAULT false, verification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text, created_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_exception_promotion_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, evidence_attachment_id uuid, decision text NOT NULL, reason text NOT NULL, before_status text NOT NULL, after_status text NOT NULL, decided_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_reconciliation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_name text NOT NULL, method text NOT NULL, candidate_count integer NOT NULL DEFAULT 0, verified_count integer NOT NULL DEFAULT 0, unresolved_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_reconciliation_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_reconciliation_runs(id), exception_id uuid NOT NULL, candidate_id uuid NOT NULL, decision text NOT NULL, authority_status text NOT NULL, rationale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_cross_validation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_dataset_id uuid NOT NULL, comparison_dataset_name text NOT NULL, comparison_source_url text, comparison_version text, comparison_authority_status text NOT NULL DEFAULT 'Reference', methodology text NOT NULL, status text NOT NULL DEFAULT 'Pending', feature_count_primary integer NOT NULL DEFAULT 0, feature_count_comparison integer NOT NULL DEFAULT 0, matched_count integer NOT NULL DEFAULT 0, mismatch_count integer NOT NULL DEFAULT 0, tolerance_note text, result_summary text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_cross_validation_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, comparison_dataset_id uuid REFERENCES gis_boundary_datasets(id) ON DELETE SET NULL, comparison_feature_code text, comparison_feature_name text, geometry_relation text, overlap_ratio numeric(12,8), centroid_distance numeric(20,8), status text NOT NULL DEFAULT 'Pending', review_required boolean NOT NULL DEFAULT true, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_evidence_acquisition_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version text NOT NULL, source_feature_id text NOT NULL, priority text NOT NULL DEFAULT 'HIGH', missing_evidence text, required_source_providers text, missing_geometry boolean NOT NULL DEFAULT true, missing_intersection boolean NOT NULL DEFAULT true, missing_identity_evidence boolean NOT NULL DEFAULT false, required_provider text, required_dataset text, required_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'OPEN', resolution_blocker text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id));